  height: 90px !important;
  min-height: 90px !important;
  max-height: 90px !important;
  overflow: hidden !important; 
  border-radius: 18px !important;
  padding: 4px 5px 4px !important;
  transition: background 120ms ease, border 120ms ease, box-shadow 120ms ease !important;
  --tile-color: {% if active %}#ffb300{% elif s in ['unavailable','unknown'] %}#777777{% else %}#19c7e6{% endif %} !important;
  --state-icon-color: {% if active %}#ffb300{% elif s in ['unavailable','unknown'] %}#777777{% else %}#19c7e6{% endif %} !important;
  --state-switch-on-color: #ffb300 !important;
  --state-switch-off-color: #19c7e6 !important;

