{% set s = states('switch.living_room_lamp_1') %}{% set active = s in ['on','open','opening','closing','playing'] %}ha-card {
  height: 90px !important;
  min-height: 90px !important;
  max-height: 90px !important;
  overflow: hidden !important; 
  border-radius: 18px !important;
  padding: 4px 5px 4px !important;
  transition: background 120ms ease, border 120ms ease, box-shadow 120ms ease !important;
  --tile-color: {% if active %}#ffb300{% elif s in ['unavailable','unknown'] %}#777777{% else %}#19c7e6{% endif %} !important;
  --state-icon-color: {% if active %}#ffb300{% elif s in ['unavailable','unknown'] %}#777777{% else %}#19c7e6{% endif %} !important;
  --state-switch-on-color: #ffb300 !important;
  --state-switch-off-color: #19c7e6 !important;

  {% if active %}
  background: rgba(255,179,0,0.24) !important;
  border: 1.5px solid rgba(255, 179, 0, 0.86) !important;
  box-shadow: 0 0 22px rgba(255, 179, 0, 0.36), inset 0 0 0 1px rgba(255,255,255,0.08) !important;
  {% elif s in ['unavailable','unknown'] %}
  background: rgba(20,13,45,0.30) !important;
  border: 1px solid rgba(255,255,255,0.08) !important;
  box-shadow: none !important;
  {% else %}
  background: rgba(20,13,45,0.45) !important;
  border: 1.5px solid rgba(25,199,230,0.86) !important;
  box-shadow: 0 0 17px rgba(25,199,230,0.32) !important;
  {% endif %}
}
ha-tile-icon {
  --tile-color: {% if active %}#ffb300{% elif s in ['unavailable','unknown'] %}#777777{% else %}#19c7e6{% endif %} !important;
  --state-icon-color: {% if active %}#ffb300{% elif s in ['unavailable','unknown'] %}#777777{% else %}#19c7e6{% endif %} !important;
  --mdc-icon-size: 42px !important;
}
ha-tile-info {
  --primary-text-color: #ffffff;
  --secondary-text-color: transparent;
}

ha-tile-icon { --mdc-icon-size: 0px !important; position: relative !important; }
ha-tile-icon::after { content: ""; position: absolute; inset: -1px; background-image: url("/local/tiles5/bulb_sys3d_{% if active %}on{% else %}off{% endif %}.png?v=sys3d4"); background-size: contain; background-repeat: no-repeat; background-position: center; pointer-events: none; }

